package com.nextrade.domain.ledger; import com.nextrade.common.enumtype.LedgerEntryType; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record TradeDebit(LedgerEntry entry) { public TradeDebit { if(entry.type()!=LedgerEntryType.TRADE_DEBIT) throw new IllegalArgumentException("Wrong ledger type"); } public static TradeDebit of(UserId user,Money amount,String reference){ return new TradeDebit(new LedgerEntry(LedgerEntryId.generate(),user,LedgerEntryType.TRADE_DEBIT,amount,reference,java.time.Instant.now())); } }